CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS freight_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_name TEXT NOT NULL, origin TEXT NOT NULL, destination TEXT NOT NULL, cargo_type TEXT NOT NULL, weight_kg NUMERIC NOT NULL CHECK(weight_kg>0), status TEXT NOT NULL DEFAULT 'NEW', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS quotes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), freight_id UUID REFERENCES freight_requests(id), distance_km NUMERIC NOT NULL, base_cost NUMERIC NOT NULL, services NUMERIC NOT NULL DEFAULT 0, margin NUMERIC NOT NULL, total NUMERIC NOT NULL, status TEXT NOT NULL DEFAULT 'DRAFT', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS operations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), freight_id UUID REFERENCES freight_requests(id), carrier TEXT, vehicle_plate TEXT, driver_name TEXT, status TEXT NOT NULL DEFAULT 'PLANNED', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS tracking_events (id BIGSERIAL PRIMARY KEY, operation_id UUID REFERENCES operations(id), lat NUMERIC, lon NUMERIC, event_type TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS incidents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), operation_id UUID REFERENCES operations(id), severity TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'OPEN', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS documents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), operation_id UUID REFERENCES operations(id), kind TEXT NOT NULL, storage_uri TEXT NOT NULL, validation_status TEXT NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS approvals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), action TEXT NOT NULL, payload JSONB NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', requested_by TEXT NOT NULL, decided_by TEXT, created_at TIMESTAMPTZ DEFAULT now(), decided_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, entity_type TEXT, entity_id TEXT, payload JSONB, trace_id UUID NOT NULL DEFAULT gen_random_uuid(), created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_tracking_operation ON tracking_events(operation_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_trace ON audit_logs(trace_id);
